<template>
  <div id="ckEditorComponent">
    <!-- TEMPORARY DIAGNOSTIC banners — disabled now that the WebView hang is fixed.
         Uncomment together with the ckDebugLogger import/calls below if this needs
         debugging again in the future.
    <div class="ckEditorDebugStep">DEBUG paso: {{ debugStep }}</div>
    <div class="ckEditorLoadError" v-if="loadError">
      <q-icon name="fas fa-triangle-exclamation" />
      {{ loadError }}
    </div>
    -->
    <ck-editor v-if="visible"
               v-model="responseValue"
               :config="configEditor"
               :editor-url="editorUrl"
               @namespaceloaded="onNamespaceLoaded"
               @ready="onEditorReady"
               :ref="`ref-${internalName}`"
               :id="`id-${internalName}`"
    />
  </div>
</template>
<script>
//Components
//Using the legacy (ES5) build explicitly: the package's default entry (dist/ckeditor.js) ships
//modern JS (arrow functions, etc.) and isn't in this project's babel transpile whitelist for
//node_modules, so it gets bundled as-is into our ES5 build — risky on older/quirky WebViews.
//dist/legacy.js is the same component pre-transpiled by the package itself.
import CKEditor from 'ckeditor4-vue/dist/legacy.js';
//Custom Plugins
//(Were temporarily disabled while ruling out a hand-built plugin as the cause of the
//WebView hang — confirmed innocent, root cause was elsewhere. Re-enabled.)
import pluginCollapsibleItem from '@imagina/qsite/_plugins/ckEditorPlugins/collapsibleItem/plugin'
import pluginGrid from '@imagina/qsite/_plugins/ckEditorPlugins/grid/plugin'
import pluginEmbed from '@imagina/qsite/_plugins/ckEditorPlugins/embed/plugin'
import pluginFa from '@imagina/qsite/_plugins/ckEditorPlugins/ckeditorfa-fa6/plugin'
//TEMPORARY diagnostic instrumentation (disabled) — see debugLogger.js header for what it
//covers. Uncomment this import + every ckDebugLogger.* call below (and the two banners in
//the template above) if this needs debugging again in the future.
//import ckDebugLogger from '@imagina/qsite/_plugins/ckEditorPlugins/debugLogger'

/* range 7px to 36px*/
let fontSizes =  Array.from({length: 30}, (_, index) => `${7+index * 1}/${7 +index * 1}px;`)
fontSizes.push('48/48px;72/72px;96/96px;')

//If the visibility check below never resolves (e.g. an IntersectionObserver quirk
//inside a WebView), force init anyway so the field doesn't stay permanently blank
const VISIBILITY_FALLBACK_MS = 1500

export default {
  props: {
    value: {default: ''},
    name: {default: null}
  },
  components: {ckEditor: CKEditor.component},
  watch: {
    value(newValue, oldValue) {
      if (newValue !== oldValue) this.responseValue = newValue
    },
    responseValue(newValue, oldValue) {
      if (newValue !== oldValue) this.$emit('input', newValue)
    }
  },
  //TEMPORARY diagnostic (disabled) — caught errors from ck-editor's own mounted() hook that
  //Vue would otherwise only send to console.error, invisible on a device with no devtools.
  //Uncomment together with the debugLogger import and the two banners in the template.
  //errorCaptured(error, vm, info) {
  //  this.loadError = `Error interno del editor (${info}): ${error.message || error}`
  //  this.debugStep = `errorCaptured (${info}): ${error.message || error}`
  //  ckDebugLogger.log('vue:errorCaptured', info, {message: error.message, stack: error.stack})
  //  return false
  //},
  //TEMPORARY diagnostic (disabled) — created()/beforeMount() only existed to log lifecycle
  //timing on screen; no functional purpose otherwise.
  //created() {
  //  ckDebugLogger.install()
  //  ckDebugLogger.log('vue:created', this.internalName)
  //},
  //beforeMount() {
  //  ckDebugLogger.log('vue:beforeMount', this.internalName)
  //},
  mounted() {
    //ckDebugLogger.log('vue:mounted', this.internalName)
    //this.debugStep = 'mounted() ejecutado'
    this.$nextTick(() => {
      //this.debugStep = 'nextTick ejecutado'
      this.init()
      this.observeVisibility()
    })
    //TEMPORARY diagnostic (disabled) — surfaced the editor script failing to load, or never
    //responding at all within 8s, directly on screen. Root cause (wrong script path/version)
    //is fixed now; uncomment if this class of failure needs to be debugged again.
    //this.scriptErrorListener = (event) => {
    //  if (event.filename && event.filename.indexOf('ckeditor4/ckeditor.js') !== -1) {
    //    this.loadError = `No se pudo cargar el script del editor (${event.message || 'error desconocido'})`
    //  }
    //}
    //window.addEventListener('error', this.scriptErrorListener, true)
    //this.scriptHangTimer = setTimeout(() => {
    //  if (this.debugStep.indexOf('namespaceloaded') === -1 && !this.loadError) {
    //    this.loadError = 'El script del editor nunca respondió (ni cargó ni dio error) despues de 8 segundos. Posible bloqueo de red a nivel nativo del WebView.'
    //    this.debugStep = 'timeout de 8s esperando namespaceloaded, sin respuesta'
    //    ckDebugLogger.log('vue:hang-timeout', 'namespaceloaded nunca llego tras 8s', {
    //      pendingResources: Array.from(ckDebugLogger.pendingResources.values())
    //    })
    //  }
    //}, 8000)
  },
  beforeDestroy() {
    //ckDebugLogger.log('vue:beforeDestroy', this.internalName)
    if (this.visibilityObserver) this.visibilityObserver.disconnect()
    if (this.visibilityTimer) clearTimeout(this.visibilityTimer)
    //if (this.scriptErrorListener) window.removeEventListener('error', this.scriptErrorListener, true)
    //if (this.scriptHangTimer) clearTimeout(this.scriptHangTimer)
  },
  //destroyed() {
  //  ckDebugLogger.log('vue:destroyed', this.internalName)
  //},
  data() {
    return {
      responseValue: '',
      //CKEditor miscalculates its toolbar/iframe size if created while an ancestor is display:none
      //(e.g. a crud-form modal that's mounted with v-show before it's opened), so we delay rendering
      //it until the container is actually visible
      visible: false,
      visibilityObserver: null,
      visibilityTimer: null,
      //Shown on-screen (not just console) so failures are visible on devices without devtools access
      loadError: null,
      //TEMPORARY diagnostic (disabled) - shows the last lifecycle step reached, directly on screen
      //debugStep: 'componente creado (antes de mounted)',
      //By default ckeditor4-vue fetches the editor script from cdn.ckeditor.com on every load.
      //If that domain is blocked/unreachable (e.g. a locked-down WebView), the editor never
      //initializes and the raw <textarea> is all that's left, with no error at all. Serving it
      //from our own origin (src/statics/ckeditor4) removes that network dependency entirely.
      //IMPORTANT: that folder must stay on CKEditor 4.22.1 — it's the last version released
      //under the free/open-source license. 4.23.0+ is "LTS" and requires a paid license key
      //(it silently refuses to initialize otherwise). Don't copy node_modules/ckeditor4 here
      //without checking its version first — npm currently resolves that dependency to a paid one.
      //Path is relative (no leading slash) on purpose, same as the rest of the built assets
      //(see dist/pwa/index.html) — this app can be deployed under a sub-path like /iadmin/,
      //and a leading slash would always resolve to the domain root instead of that sub-path.
      editorUrl: 'ckeditor4/ckeditor.js',
      configEditor: {
        allowedContent: true,
        filebrowserBrowseUrl: this.$router.resolve({name: 'app.media.select'}).href,
        extraPlugins: 'colorbutton,colordialog,justify,collapsibleItem,font,btgrid,simplebox,ckeditorfa',
        embed_provider: '//iframe.ly/api/oembed?url={url}&callback={callback}&api_key=7e0aa12b0cd2c01651346b',
        //CKEditor waits for this stylesheet to load *inside its own iframe* before finishing
        //initialization (contentDom/dataReady/instanceReady). An external CDN request made
        //from that iframe's context is exactly the kind of request some embedded WebViews
        //never complete (neither load nor error) — self-hosting removes that dependency too,
        //same reasoning as editorUrl above. Matches @fortawesome/fontawesome-free 6.5.2.
        contentsCss: 'fontawesome6/css/all.min.css',
        fontSize_sizes: fontSizes.join(''),
        versionCheck: false
      }
    }
  },
  computed: {
    internalName(){
      return this.name || this.$uid()
    }
  },
  methods: {
    init() {
      this.responseValue = this.$clone(this.value)
    },
    //Delay creating the CKEditor instance until the container has an actual size
    //(handles being mounted inside a v-show'ed modal/tab that starts hidden)
    observeVisibility() {
      //this.debugStep = 'observeVisibility() ejecutado'
      //If it's already visible (normal case: not inside a hidden ancestor), show right away
      if (this.$el && this.$el.getClientRects().length) {
        //this.debugStep = 'visible desde el inicio (getClientRects)'
        this.visible = true
        return
      }
      //No IntersectionObserver support: fall back to the previous behavior
      if (typeof IntersectionObserver === 'undefined') {
        //this.debugStep = 'sin soporte de IntersectionObserver, mostrando directo'
        this.visible = true
        return
      }
      //this.debugStep = 'esperando IntersectionObserver / timeout'
      this.visibilityObserver = new IntersectionObserver((entries) => {
        if (entries[0].isIntersecting) this.showEditor('IntersectionObserver')
      })
      this.visibilityObserver.observe(this.$el)
      //Safety net: some WebViews have been observed to miscalculate layout/intersection
      //timing versus a real browser tab, which would otherwise leave the field blank forever
      this.visibilityTimer = setTimeout(() => this.showEditor('timeout'), VISIBILITY_FALLBACK_MS)
    },
    showEditor(fromWhere) {
      if (this.visible) return
      //this.debugStep = `visible=true (por ${fromWhere}), montando <ck-editor>`
      this.visible = true
      if (this.visibilityObserver) this.visibilityObserver.disconnect()
      if (this.visibilityTimer) clearTimeout(this.visibilityTimer)
    },
    //On name space loaded
    onNamespaceLoaded(CKEDITOR) {
      //if (this.scriptHangTimer) clearTimeout(this.scriptHangTimer)
      //this.debugStep = 'namespaceloaded disparado (CKEDITOR cargo bien)'
      //ckDebugLogger.log('vue:namespaceloaded', this.internalName)
      //TEMPORARY diagnostic (disabled) - instruments CKEDITOR namespace/plugins/instance
      //events. Uncomment together with the debugLogger import if needed again.
      //try {
      //  ckDebugLogger.instrumentCKEditor(CKEDITOR)
      //} catch (error) {
      //  ckDebugLogger.log('vue:instrumentCKEditor-ERROR', error.message, {stack: error.stack})
      //}
      //Load custom plugins — isolated so a broken plugin can't take the others down
      ;[pluginCollapsibleItem, pluginGrid, pluginEmbed, pluginFa].forEach(plugin => {
        try {
          plugin.load(CKEDITOR)
        } catch (error) {
          //A second (or later) CKEditor field on the same page re-runs this plugin's own
          //internal CKEDITOR.plugins.add(...) call, which CKEditor rejects for a name
          //that's already registered — the existing registration is still perfectly usable,
          //so this specific case isn't a real failure, just noisy if surfaced as one
          const alreadyRegistered = /already registered/i.test(error.message || '')
          if (!alreadyRegistered) {
            console.error('[ckEditor] plugin failed to load:', plugin, error)
            this.loadError = `No se pudo cargar un complemento del editor: ${error.message || error}`
          }
        }
      })
      try {
        CKEDITOR.dtd.$removeEmpty['span'] = false
      } catch (error) {
        console.error('[ckEditor] namespace setup failed:', error)
        this.loadError = `Error al inicializar el editor: ${error.message || error}`
      }
    },
    onEditorReady() {
      //this.debugStep = 'ready disparado (editor completamente listo)'
      //ckDebugLogger.log('vue:ready', this.internalName)
    }
    //TEMPORARY diagnostic (disabled) - surfaced script load failures on screen. Uncomment
    //together with its @scriptloaderror binding in the template if needed again.
    //,onScriptLoadError(error) {
    //  console.error('[ckEditor] script load failed:', error)
    //  this.debugStep = 'scriptloaderror: ' + (error && (error.message || error))
    //  this.loadError = `No se pudo cargar el script del editor (${(error && error.message) || 'error desconocido'})`
    //  ckDebugLogger.log('vue:scriptloaderror', (error && error.message) || String(error), {stack: error && error.stack})
    //}
  }
}
</script>
<style lang="stylus">
#ckEditorComponent
  /* TEMPORARY DIAGNOSTIC banners styling (disabled) — uncomment together with the
     matching divs in the template if this needs debugging again.
  .ckEditorDebugStep
    background #E3F2FD
    color #0D47A1
    border 1px solid #90CAF9
    border-radius 4px
    padding 6px 10px
    margin-bottom 8px
    font-size 12px
    font-family monospace

  .ckEditorLoadError
    display flex
    align-items center
    gap 8px
    background #FDEDED
    color #C0392B
    border 1px solid #F5C6C6
    border-radius 4px
    padding 8px 12px
    margin-bottom 8px
    font-size 13px
  */

  .btn-content-toolbar
    background-size 16px
    height 16px
    width 16px

  #iconToolbarCollapsibleitem
    background-image url("../../_plugins/ckEditorPlugins/collapsibleItem/collapsibleitem.png")


  #iconToolbarGrid
    background-image url("../../_plugins/ckEditorPlugins/grid/grid.png")

  #iconToolbarEmbed
    background-image url("../../_plugins/ckEditorPlugins/embed/embed.png")

  .cke_button__ckeditorfa_icon
    background-image url("../../_plugins/ckEditorPlugins/ckeditorfa-fa6/icons/ckeditorfa.png") !important


/* ckeditor-fa pluging */
#ckeditor-fa-preview {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100px
}

#ckeditor-fa-icons{
  text-align:center;
  white-space:normal;
  width:100%;
  height: 400px;
  padding-top : 20px;
  padding-bottom: 20px;
  overflow:auto
  background-color: #f0f1f3;
}
#ckeditor-fa-icons button {
  display:inline-block;
  width: 100px;
  padding: 5px;
  text-align:center;
  vertical-align:top
  background-color: #ffffff;
  border-radius: 4px !important
  border: 2px solid #f0f1f3 !important
}

#ckeditor-fa-icons button:hover {
  /* transform: scale(1.2) */
  transition: all 0.1s ease-in-out;
  border: 2px solid $primary !important
}

#ckeditor-fa-icons button span{
  font-size: 28px;
  display:block;
  text-align:center
}

#ckeditor-fa-icons button p {
  font-size: 14px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis
}

.faSelect{display:block !important}
</style>
